-- CTOD 001: add Commercial Tire market/corporate roles and five role-specific review questions each.
with c as (select id company_id from public.companies where slug='commercial-tire'), new_roles(title,sort_order) as (values ('Market Manager Level 1',15),('Market Manager Level 2',16),('Market Manager Level 3',17),('AP Specialist',18),('IT Administrator',19),('Administrative Assistant',20),('Director of Sales',21),('Regional Sales Manager',22),('Human Resources',23)) insert into public.roles(company_id,title,sort_order,active) select c.company_id,n.title,n.sort_order,true from c cross join new_roles n on conflict(company_id,title) do update set sort_order=excluded.sort_order,active=true;

with c as (select id company_id from public.companies where slug='commercial-tire'), cfg as (select id config_id from public.configuration_versions where company_id=(select company_id from c) and status='published' order by published_at desc nulls last,created_at desc limit 1), q(role_title,code,ord,category,text) as (values
('Market Manager Level 1','MM1-01',1,'Location Performance','How effectively does this employee improve sales, profit, service, and execution across assigned locations?'),('Market Manager Level 1','MM1-02',2,'Manager Coaching','How effectively does this employee coach general managers and build stronger store leadership?'),('Market Manager Level 1','MM1-03',3,'Operational Consistency','How consistently does this employee drive standards, accountability, and follow-through across locations?'),('Market Manager Level 1','MM1-04',4,'People Development','How effectively does this employee identify talent, develop bench strength, and address performance gaps?'),('Market Manager Level 1','MM1-05',5,'Communication & Priorities','How clearly does this employee communicate priorities and keep locations aligned with company expectations?'),
('Market Manager Level 2','MM2-01',1,'Market Performance','How effectively does this employee deliver sustained financial and operational improvement across the market?'),('Market Manager Level 2','MM2-02',2,'Leadership Development','How effectively does this employee develop general managers and emerging multi-location leaders?'),('Market Manager Level 2','MM2-03',3,'Strategic Execution','How effectively does this employee convert company strategy into measurable market-level execution?'),('Market Manager Level 2','MM2-04',4,'Cross-Location Talent','How effectively does this employee move, retain, and develop talent across multiple locations?'),('Market Manager Level 2','MM2-05',5,'Problem Solving','How effectively does this employee recognize market-wide risks and solve issues before they become larger problems?'),
('Market Manager Level 3','MM3-01',1,'Enterprise Leadership','How effectively does this employee lead a large or complex market with strong long-term business health?'),('Market Manager Level 3','MM3-02',2,'Leader of Leaders','How effectively does this employee develop high-performing general managers and other market-level leaders?'),('Market Manager Level 3','MM3-03',3,'Growth Strategy','How effectively does this employee identify and execute growth opportunities across the market?'),('Market Manager Level 3','MM3-04',4,'Succession & Bench','How effectively does this employee build succession depth for critical leadership roles?'),('Market Manager Level 3','MM3-05',5,'Enterprise Alignment','How effectively does this employee align market decisions with company-wide priorities and culture?'),
('AP Specialist','APS-01',1,'Invoice Accuracy','How accurately and efficiently does this employee process invoices, credits, and payment-related transactions?'),('AP Specialist','APS-02',2,'Vendor Reconciliation','How effectively does this employee resolve vendor discrepancies and maintain accurate account records?'),('AP Specialist','APS-03',3,'Controls & Compliance','How consistently does this employee follow approval controls, documentation standards, and financial procedures?'),('AP Specialist','APS-04',4,'Timeliness','How consistently does this employee meet payment cycles, deadlines, and internal service expectations?'),('AP Specialist','APS-05',5,'Problem Resolution','How effectively does this employee identify and resolve accounts-payable issues with stores, vendors, and internal teams?'),
('IT Administrator','ITA-01',1,'System Reliability','How effectively does this employee maintain reliable systems, devices, networks, and user access?'),('IT Administrator','ITA-02',2,'Security','How consistently does this employee protect company systems through sound security, access, and update practices?'),('IT Administrator','ITA-03',3,'User Support','How effectively does this employee diagnose and resolve user technology issues with appropriate urgency?'),('IT Administrator','ITA-04',4,'Administration & Documentation','How effectively does this employee maintain technical documentation, inventories, standards, and administrative controls?'),('IT Administrator','ITA-05',5,'Improvement & Scalability','How effectively does this employee identify technology improvements that increase reliability, efficiency, or scalability?'),
('Administrative Assistant','AA-01',1,'Organization','How effectively does this employee organize schedules, documents, information, and administrative priorities?'),('Administrative Assistant','AA-02',2,'Communication','How professionally and accurately does this employee communicate with employees, customers, vendors, and leaders?'),('Administrative Assistant','AA-03',3,'Follow-Through','How consistently does this employee complete assigned administrative work accurately and on time?'),('Administrative Assistant','AA-04',4,'Confidentiality & Judgment','How consistently does this employee use good judgment and protect confidential or sensitive information?'),('Administrative Assistant','AA-05',5,'Support & Initiative','How effectively does this employee anticipate needs and improve the efficiency of the leaders or teams they support?'),
('Director of Sales','DOS-01',1,'Sales Strategy','How effectively does this employee build and execute a company-wide sales strategy that drives profitable growth?'),('Director of Sales','DOS-02',2,'Sales Leadership','How effectively does this employee develop regional and field sales leaders and create accountability for results?'),('Director of Sales','DOS-03',3,'Customer Growth','How effectively does this employee expand key accounts, customer retention, and strategic market opportunities?'),('Director of Sales','DOS-04',4,'Sales Analytics','How effectively does this employee use sales, margin, pipeline, and market data to direct resources and priorities?'),('Director of Sales','DOS-05',5,'Cross-Functional Alignment','How effectively does this employee align sales with operations, pricing, inventory, marketing, and company strategy?'),
('Regional Sales Manager','RSM-01',1,'Regional Sales Performance','How effectively does this employee grow profitable sales across the assigned region?'),('Regional Sales Manager','RSM-02',2,'Sales Team Development','How effectively does this employee coach, develop, and hold salespeople accountable for performance?'),('Regional Sales Manager','RSM-03',3,'Account Strategy','How effectively does this employee develop key accounts, prospecting discipline, and customer-retention strategies?'),('Regional Sales Manager','RSM-04',4,'Pipeline & Execution','How consistently does this employee maintain a healthy pipeline and convert sales plans into measurable activity?'),('Regional Sales Manager','RSM-05',5,'Market Intelligence','How effectively does this employee use market, competitor, pricing, and customer information to improve regional results?'),
('Human Resources','HR-01',1,'Employee Relations','How effectively does this employee handle employee relations issues with consistency, judgment, and professionalism?'),('Human Resources','HR-02',2,'Talent & Staffing','How effectively does this employee support recruiting, onboarding, retention, and internal talent movement?'),('Human Resources','HR-03',3,'Policy & Compliance','How consistently does this employee apply company policy, employment practices, and required documentation?'),('Human Resources','HR-04',4,'Leader Support','How effectively does this employee coach managers through people decisions, performance concerns, and workplace issues?'),('Human Resources','HR-05',5,'Culture & Development','How effectively does this employee strengthen culture, employee development, and organizational health?')) insert into public.question_definitions(company_id,config_version_id,role_id,question_code,section_code,section_name,question_text,category,active,sort_order,question_weight,section_weight,requires_rating,requires_reason,notes_required_for_exceptional,notes_required_for_unsatisfactory) select c.company_id,cfg.config_id,r.id,q.code,'SEC-ROLE','Current Role Performance',q.text,q.category,true,q.ord,0.2,0.55,true,true,true,true from q join public.roles r on r.title=q.role_title and r.company_id=(select company_id from c) cross join c cross join cfg on conflict(config_version_id,question_code) do update set role_id=excluded.role_id,question_text=excluded.question_text,category=excluded.category,active=true,sort_order=excluded.sort_order;

with q as (select q.id question_id,q.company_id,q.config_version_id,q.role_id,q.category from public.question_definitions q join public.roles r on r.id=q.role_id where r.title in ('Market Manager Level 1','Market Manager Level 2','Market Manager Level 3','AP Specialist','IT Administrator','Administrative Assistant','Director of Sales','Regional Sales Manager','Human Resources') and r.company_id=(select id from public.companies where slug='commercial-tire')), ratings(code,base) as (values ('EXCEPTIONAL',100),('EXCEEDS',200),('MEETS',300),('NEEDS_IMPROVEMENT',400),('UNSATISFACTORY',500)), variants(v) as (values (1),(2),(3)) insert into public.reason_definitions(company_id,config_version_id,label,reason_type,rating_code,category,role_id,active,sort_order,question_id) select q.company_id,q.config_version_id,case r.code when 'EXCEPTIONAL' then (array['Consistently sets the standard for others in this area.','Demonstrates exceptional consistency and follow-through in this area.','Creates a clear positive impact well beyond normal role expectations in this area.'])[v.v] when 'EXCEEDS' then (array['Regularly performs above role expectations in this area.','Shows strong consistency and requires little follow-up in this area.','Frequently adds value beyond normal role expectations in this area.'])[v.v] when 'MEETS' then (array['Consistently meets the role standard in this area.','Follows through at the expected level in this area.','Reliably handles this responsibility at the expected level.'])[v.v] when 'NEEDS_IMPROVEMENT' then (array['Performance is inconsistent in this area.','Needs additional coaching or follow-through to meet the standard consistently in this area.','Does not yet meet the role standard consistently in this area.'])[v.v] else (array['Frequently performs below the required standard in this area.','Creates significant risk or disruption through performance in this area.','Has not met the minimum standard in this area even after clear coaching.'])[v.v] end,'review_role',r.code,q.category,q.role_id,true,r.base+v.v,q.question_id from q cross join ratings r cross join variants v where not exists(select 1 from public.reason_definitions rd where rd.question_id=q.question_id and rd.rating_code=r.code and rd.sort_order=r.base+v.v);